def solve_bruteforce(g, o):
    H,W=len(g),len(g[0])
    cs=[(r,c) for r in range(H) for c in range(W) if g[r][c]==8]
    r0=min(r for r,_ in cs); r1=max(r for r,_ in cs); c0=min(c for _,c in cs); c1=max(c for _,c in cs)
    hs=r1-r0+1; ws=c1-c0+1
    marks=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=0 and g[r][c]!=8]
    hm=max(r for r,_,_ in marks)-min(r for r,_,_ in marks)+1
    wm=max(c for _,c,_ in marks)-min(c for _,c,_ in marks)+1
    res=[]
    for a in (1,2):
        for b in range(-hm, hs-a*hm+1):
            for c in (1,2):
                for d in range(-wm, ws-c*wm+1):
                    ok=True; out=[row[:] for row in g]
                    for r,cc,v in marks:
                        rr=r0+a*(r-min(r for r,_,_ in marks))+b
                        cc2=c0+c*(cc-min(c for _,cc,_ in marks))+d
                        if 0<=rr<H and 0<=cc2<W:
                            for dr in range(hs//a):
                                for dc in range(ws//c):
                                    out[rr+dr][cc2+dc]=v
                    if out==o: res.append((a,b,c,d))
    return res
