def f(inp):
    H,W=len(inp),len(inp[0])
    from collections import Counter
    cnt=Counter(v for row in inp for v in row)
    bg=cnt.most_common(1)[0][0]
    # dominant non-bg color = shape color(s); find most common non-bg forming large blocks
    out=[[bg]*W for _ in range(H)]
    seen=set()
    for r in range(H):
        for c in range(W):
            if inp[r][c]!=bg and (r,c) not in seen:
                # flood fill / collect component
                stack=[(r,c)]; comp=[]
                while stack:
                    rr,cc=stack.pop()
                    if (rr,cc) in seen: continue
                    seen.add((rr,cc)); comp.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and inp[nr][nc]==inp[r][c] and (nr,nc) not in seen:
                            stack.append((nr,nc))
                if len(comp)>1:
                    col=inp[r][c]
                    for rr,cc in comp: out[rr][cc]=col
    return out

